/*
 * Self-test for the shader seed / PSO preparation path.
 *
 * Compiles the real (patched) loader + built-in compile wrapper sliced out of
 * rsx_live_draw.c (rsp_loader_slice.inc, generated by build_candidate.py) and
 * the real runtime header, then drives them with a real D3D12 device and the
 * real MacrossShaderPrep.exe:
 *
 *   rsp_selftest.exe <work dir (new)> <seed fixture dir> <MacrossShaderPrep.exe> [--warp]
 */
#define COBJMACROS_NOT_USED
#include <windows.h>
#include <initguid.h>
#include <d3d12.h>
#include <dxgi1_4.h>
#include <d3dcompiler.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include "rsx_shader_prep_runtime.h"

typedef uint8_t u8; typedef uint32_t u32; typedef uint64_t u64;
#define SHADER_DISK_CACHE_MAGIC   0x43535A59u
#define SHADER_DISK_CACHE_VERSION 2u
#define SHADER_DISK_CACHE_MAX_BLOB (4u * 1024u * 1024u)
typedef struct { u32 magic, version, stage, source_length, blob_length, reserved; u64 source_hash; } shader_disk_cache_header;
static int g_ld_shader_disk_ready = -1;
static char g_ld_shader_disk_dir[MAX_PATH];
static u64 g_ld_shader_disk_hits[2], g_ld_shader_disk_misses[2], g_ld_shader_disk_writes[2], g_ld_shader_disk_rejects;
static u32 g_ld_frames = 7;
static u64 fnv1a(const void* data, u32 n, u64 h) { return rsp_fnv1a(data, n, h); }
#include "rsp_loader_slice.inc"

static int g_failures, g_checks;
#define CHECK(cond) do { g_checks++; if (!(cond)) { g_failures++; \
    fprintf(stderr, "FAIL %s:%d: %s\n", __FILE__, __LINE__, #cond); } } while (0)

static char g_work[MAX_PATH], g_prep[MAX_PATH], g_user[MAX_PATH], g_seed[MAX_PATH];
static int g_warp;

static void* read_file(const char* path, size_t* size)
{
    FILE* f = fopen(path, "rb"); if (!f) return NULL;
    fseek(f, 0, SEEK_END); long n = ftell(f); fseek(f, 0, SEEK_SET);
    void* p = malloc((size_t)n + 1); if (p && fread(p, 1, (size_t)n, f) != (size_t)n) { free(p); p = NULL; }
    fclose(f); if (size) *size = (size_t)n; return p;
}
static int write_file(const char* path, const void* p, size_t n)
{
    FILE* f = fopen(path, "wb"); if (!f) return 0;
    const int ok = fwrite(p, 1, n, f) == n; fclose(f); return ok;
}
static int exists(const char* path) { return GetFileAttributesA(path) != INVALID_FILE_ATTRIBUTES; }

typedef struct { shader_disk_cache_header h; char* source; u8* blob; char name[64]; } fixture;
static int load_fixture(const char* path, fixture* fx)
{
    size_t n; u8* p = (u8*)read_file(path, &n);
    if (!p || n < sizeof fx->h) return 0;
    memcpy(&fx->h, p, sizeof fx->h);
    fx->source = (char*)malloc(fx->h.source_length); fx->blob = (u8*)malloc(fx->h.blob_length);
    memcpy(fx->source, p + sizeof fx->h, fx->h.source_length);
    memcpy(fx->blob, p + sizeof fx->h + fx->h.source_length, fx->h.blob_length);
    const char* slash = strrchr(path, '\\'); snprintf(fx->name, sizeof fx->name, "%s", slash ? slash + 1 : path);
    free(p); return 1;
}

/* Runs the preparation tool; returns exit code, stdout captured to out. */
static int run_prep(const char* extra, char* out, size_t cap)
{
    char cmd[4096], log[MAX_PATH];
    snprintf(log, sizeof log, "%s\\prep-%lu.log", g_work, (unsigned long)GetTickCount());
    snprintf(cmd, sizeof cmd, "\"\"%s\" --cache-dir \"%s\" --seed-dir \"%s\" --inventory \"%s\\none.bin\" %s %s > \"%s\"\"",
             g_prep, g_user, g_seed, g_work, g_warp ? "--warp" : "", extra ? extra : "", log);
    const int code = system(cmd);
    size_t n = 0; char* text = (char*)read_file(log, &n);
    if (text && out) { text[n] = 0; snprintf(out, cap, "%s", text); }
    free(text);
    return code;
}
static long json_last_number(const char* text, const char* key)
{
    char pattern[64]; snprintf(pattern, sizeof pattern, "\"%s\":", key);
    const char* last = NULL; for (const char* p = strstr(text, pattern); p; p = strstr(p + 1, pattern)) last = p;
    return last ? strtol(last + strlen(pattern), NULL, 10) : -1;
}

static void test_dxbc(const char* fixtures)
{
    char pattern[MAX_PATH]; snprintf(pattern, sizeof pattern, "%s\\*.bin", fixtures);
    WIN32_FIND_DATAA fd; HANDLE h = FindFirstFileA(pattern, &fd);
    int valid = 0, total = 0, corrupt_detected = 0;
    if (h != INVALID_HANDLE_VALUE) {
        do {
            char path[MAX_PATH]; snprintf(path, sizeof path, "%s\\%s", fixtures, fd.cFileName);
            fixture fx; if (!load_fixture(path, &fx)) continue;
            total++;
            valid += rsp_dxbc_valid(fx.blob, fx.h.blob_length);
            fx.blob[fx.h.blob_length / 2] ^= 0x40;
            corrupt_detected += !rsp_dxbc_valid(fx.blob, fx.h.blob_length);
            free(fx.source); free(fx.blob);
        } while (FindNextFileA(h, &fd));
        FindClose(h);
    }
    printf("dxbc fixtures=%d valid=%d corrupt_detected=%d\n", total, valid, corrupt_detected);
    CHECK(total > 0 && valid == total && corrupt_detected == total);
}

static void copy_into(const char* dir, const fixture* fx, int flip_blob)
{
    char path[MAX_PATH]; snprintf(path, sizeof path, "%s\\%s", dir, fx->name);
    size_t n = sizeof fx->h + fx->h.source_length + fx->h.blob_length;
    u8* p = (u8*)malloc(n);
    memcpy(p, &fx->h, sizeof fx->h); memcpy(p + sizeof fx->h, fx->source, fx->h.source_length);
    memcpy(p + sizeof fx->h + fx->h.source_length, fx->blob, fx->h.blob_length);
    if (flip_blob) p[sizeof fx->h + fx->h.source_length + fx->h.blob_length / 2] ^= 0x40;
    write_file(path, p, n); free(p);
}

static void test_loader(const fixture* vs, const fixture* ps)
{
    copy_into(g_seed, vs, 0);
    copy_into(g_seed, ps, 1);   /* seed entry with corrupt bytecode */
    /* 1: exact source -> seed hit with identical bytecode */
    ID3DBlob* b = shader_disk_cache_load('V', vs->source, vs->h.source_length, vs->h.source_hash);
    CHECK(b && b->lpVtbl->GetBufferSize(b) == vs->h.blob_length &&
          memcmp(b->lpVtbl->GetBufferPointer(b), vs->blob, vs->h.blob_length) == 0);
    if (b) b->lpVtbl->Release(b);
    CHECK(g_rsp.seed_hits[RSP_STAGE_V] == 1 && g_ld_shader_seed_hits == 1);
    /* 2: same hash/length, different source -> rejected, seed kept */
    vs->source[vs->h.source_length / 2] ^= 1;
    b = shader_disk_cache_load('V', vs->source, vs->h.source_length, vs->h.source_hash);
    vs->source[vs->h.source_length / 2] ^= 1;
    CHECK(!b && g_rsp.seed_rejects[RSP_REJECT_SOURCE] == 1);
    char seed_path[MAX_PATH]; snprintf(seed_path, sizeof seed_path, "%s\\%s", g_seed, vs->name);
    CHECK(exists(seed_path));
    /* 3: missing entry -> plain miss */
    b = shader_disk_cache_load('V', vs->source, vs->h.source_length, vs->h.source_hash ^ 1);
    CHECK(!b && g_rsp.seed_rejects[RSP_REJECT_SOURCE] == 1 && g_rsp.seed_rejects[RSP_REJECT_FORMAT] == 0);
    /* 4: corrupt DXBC in the seed -> rejected (DXBC), not used */
    b = shader_disk_cache_load('P', ps->source, ps->h.source_length, ps->h.source_hash);
    CHECK(!b && g_rsp.seed_rejects[RSP_REJECT_DXBC] == 1);
    /* 5: user cache has precedence over seed */
    copy_into(g_user, vs, 0);
    b = shader_disk_cache_load('V', vs->source, vs->h.source_length, vs->h.source_hash);
    CHECK(b && g_rsp.user_hits[RSP_STAGE_V] == 1 && g_rsp.seed_hits[RSP_STAGE_V] == 1);
    if (b) b->lpVtbl->Release(b);
    /* 6: corrupt user entry -> deleted, then seed serves the exact source */
    copy_into(g_user, vs, 1);
    b = shader_disk_cache_load('V', vs->source, vs->h.source_length, vs->h.source_hash);
    char user_path[MAX_PATH]; snprintf(user_path, sizeof user_path, "%s\\%s", g_user, vs->name);
    CHECK(b && g_rsp.user_rejects[RSP_REJECT_DXBC] == 1 && g_rsp.seed_hits[RSP_STAGE_V] == 2 && !exists(user_path));
    if (b) b->lpVtbl->Release(b);
    /* 7: RSX_NO_SHADER_SEED disables the seed */
    _putenv_s("RSX_NO_SHADER_SEED", "1");
    b = shader_disk_cache_load('V', vs->source, vs->h.source_length, vs->h.source_hash);
    CHECK(!b && g_rsp.seed_hits[RSP_STAGE_V] == 2);
    _putenv_s("RSX_NO_SHADER_SEED", "");
    printf("loader checks done seed_hits=%llu user_hits=%llu rejects{user dxbc=%llu seed src=%llu dxbc=%llu}\n",
           (unsigned long long)g_rsp.seed_hits[0], (unsigned long long)g_rsp.user_hits[0],
           (unsigned long long)g_rsp.user_rejects[2], (unsigned long long)g_rsp.seed_rejects[1],
           (unsigned long long)g_rsp.seed_rejects[2]);
}

static const char k_builtin[] =
    "float4 vs(uint i:SV_VertexID):SV_Position{return float4((i&1)*2-1.0,(i>>1)*2-1.0,0,1);}\n"
    "float4 ps(float4 p:SV_Position):SV_Target{return float4(p.xy*0.001,0,1);}\n";

static void test_builtin(void)
{
    const u64 compiles = g_rsp.compiles[RSP_STAGE_B];
    ID3DBlob *a = NULL, *b = NULL, *c = NULL, *err = NULL;
    HRESULT hr = ld_builtin_compile(k_builtin, sizeof k_builtin - 1, "selftest", NULL, NULL, "ps", "ps_5_0",
                                    D3DCOMPILE_OPTIMIZATION_LEVEL3, 0, &a, &err);
    CHECK(SUCCEEDED(hr) && a && g_rsp.compiles[RSP_STAGE_B] == compiles + 1);
    if (err) { err->lpVtbl->Release(err); err = NULL; }
    hr = ld_builtin_compile(k_builtin, sizeof k_builtin - 1, "selftest", NULL, NULL, "ps", "ps_5_0",
                            D3DCOMPILE_OPTIMIZATION_LEVEL3, 0, &b, &err);
    CHECK(SUCCEEDED(hr) && b && g_rsp.compiles[RSP_STAGE_B] == compiles + 1 && g_rsp.user_hits[RSP_STAGE_B] == 1);
    CHECK(a && b && a->lpVtbl->GetBufferSize(a) == b->lpVtbl->GetBufferSize(b) &&
          memcmp(a->lpVtbl->GetBufferPointer(a), b->lpVtbl->GetBufferPointer(b), a->lpVtbl->GetBufferSize(a)) == 0);
    /* Move the stored entry into the seed: empty user cache -> seed hit. */
    char pattern[MAX_PATH]; snprintf(pattern, sizeof pattern, "%s\\B_*.bin", g_user);
    WIN32_FIND_DATAA fd; HANDLE h = FindFirstFileA(pattern, &fd);
    CHECK(h != INVALID_HANDLE_VALUE);
    if (h != INVALID_HANDLE_VALUE) {
        char from[MAX_PATH], to[MAX_PATH];
        snprintf(from, sizeof from, "%s\\%s", g_user, fd.cFileName); snprintf(to, sizeof to, "%s\\%s", g_seed, fd.cFileName);
        CHECK(MoveFileExA(from, to, MOVEFILE_REPLACE_EXISTING));
        FindClose(h);
    }
    hr = ld_builtin_compile(k_builtin, sizeof k_builtin - 1, "selftest", NULL, NULL, "ps", "ps_5_0",
                            D3DCOMPILE_OPTIMIZATION_LEVEL3, 0, &c, &err);
    CHECK(SUCCEEDED(hr) && c && g_rsp.compiles[RSP_STAGE_B] == compiles + 1 && g_rsp.seed_hits[RSP_STAGE_B] == 1);
    if (c) c->lpVtbl->Release(c);
    /* Different flags -> different identity -> real compile. */
    hr = ld_builtin_compile(k_builtin, sizeof k_builtin - 1, "selftest", NULL, NULL, "ps", "ps_5_0", 0, 0, &c, &err);
    CHECK(SUCCEEDED(hr) && c && g_rsp.compiles[RSP_STAGE_B] == compiles + 2);
    if (c) c->lpVtbl->Release(c);
    /* Compile errors pass through unchanged and are not cached. */
    hr = ld_builtin_compile("float4 broken(", 14, "selftest", NULL, NULL, "ps", "ps_5_0", 0, 0, &c, &err);
    CHECK(FAILED(hr) && err);
    if (err) err->lpVtbl->Release(err);
    if (a) a->lpVtbl->Release(a);
    if (b) b->lpVtbl->Release(b);
    printf("builtin checks done compiles=%llu seed_hits=%llu user_hits=%llu\n",
           (unsigned long long)g_rsp.compiles[2], (unsigned long long)g_rsp.seed_hits[2], (unsigned long long)g_rsp.user_hits[2]);
}

/* Minimal pipeline in the game's shape: ATTRn inputs, main root signature. */
static const char k_vs[] = "struct I{float4 p:ATTR0;float4 c:ATTR3;};struct O{float4 p:SV_Position;float4 c:COLOR0;};"
                           "O main(I i){O o;o.p=i.p;o.c=i.c;return o;}";
static const char k_ps[] = "float4 main(float4 p:SV_Position,float4 c:COLOR0):SV_Target{return c;}";

typedef struct { ID3D12Device* dev; ID3D12RootSignature* root; ID3DBlob *vs, *ps; u64 vs_hash, ps_hash; u32 vs_len, ps_len; } gpu;

static int make_gpu(gpu* g)
{
    memset(g, 0, sizeof *g);
    HRESULT hr;
    if (g_warp) {
        IDXGIFactory4* f = NULL; IDXGIAdapter* a = NULL;
        CreateDXGIFactory1(&IID_IDXGIFactory4, (void**)&f);
        f->lpVtbl->EnumWarpAdapter(f, &IID_IDXGIAdapter, (void**)&a);
        hr = D3D12CreateDevice((IUnknown*)a, D3D_FEATURE_LEVEL_11_0, &IID_ID3D12Device, (void**)&g->dev);
        a->lpVtbl->Release(a); f->lpVtbl->Release(f);
    } else {
        hr = D3D12CreateDevice(NULL, D3D_FEATURE_LEVEL_11_0, &IID_ID3D12Device, (void**)&g->dev);
    }
    if (FAILED(hr)) return 0;
    D3D12_ROOT_PARAMETER p = {0};
    p.ParameterType = D3D12_ROOT_PARAMETER_TYPE_CBV; p.ShaderVisibility = D3D12_SHADER_VISIBILITY_VERTEX;
    D3D12_ROOT_SIGNATURE_DESC rsd = {0};
    rsd.NumParameters = 1; rsd.pParameters = &p; rsd.Flags = D3D12_ROOT_SIGNATURE_FLAG_ALLOW_INPUT_ASSEMBLER_INPUT_LAYOUT;
    ID3DBlob *sig = NULL, *err = NULL;
    if (FAILED(D3D12SerializeRootSignature(&rsd, D3D_ROOT_SIGNATURE_VERSION_1, &sig, &err))) return 0;
    hr = g->dev->lpVtbl->CreateRootSignature(g->dev, 0, sig->lpVtbl->GetBufferPointer(sig), sig->lpVtbl->GetBufferSize(sig),
                                             &IID_ID3D12RootSignature, (void**)&g->root);
    if (SUCCEEDED(hr)) rsp_rt_register_root(sig->lpVtbl->GetBufferPointer(sig), sig->lpVtbl->GetBufferSize(sig), g->root);
    sig->lpVtbl->Release(sig);
    g->vs_len = (u32)strlen(k_vs); g->ps_len = (u32)strlen(k_ps);
    g->vs_hash = fnv1a(k_vs, g->vs_len, RSP_FNV_SEED); g->ps_hash = fnv1a(k_ps, g->ps_len, RSP_FNV_SEED);
    if (FAILED(D3DCompile(k_vs, g->vs_len, "xvs", NULL, NULL, "main", "vs_5_0", 0, 0, &g->vs, NULL)) ||
        FAILED(D3DCompile(k_ps, g->ps_len, "xps", NULL, NULL, "main", "ps_5_0", 0, 0, &g->ps, NULL))) return 0;
    /* As in the renderer: compiled shaders land in the user cache. */
    shader_disk_cache_store('V', k_vs, g->vs_len, g->vs_hash, g->vs);
    shader_disk_cache_store('P', k_ps, g->ps_len, g->ps_hash, g->ps);
    return SUCCEEDED(hr);
}

static void make_desc(const gpu* g, D3D12_GRAPHICS_PIPELINE_STATE_DESC* pd, D3D12_INPUT_ELEMENT_DESC il[2], int variant)
{
    memset(pd, 0, sizeof *pd);
    D3D12_INPUT_ELEMENT_DESC a = { "ATTR", 0, DXGI_FORMAT_R32G32B32A32_FLOAT, 0, 0, D3D12_INPUT_CLASSIFICATION_PER_VERTEX_DATA, 0 };
    D3D12_INPUT_ELEMENT_DESC b = { "ATTR", 3, DXGI_FORMAT_R32G32B32A32_FLOAT, 0, 48, D3D12_INPUT_CLASSIFICATION_PER_VERTEX_DATA, 0 };
    il[0] = a; il[1] = b;
    pd->pRootSignature = g->root;
    pd->VS.pShaderBytecode = g->vs->lpVtbl->GetBufferPointer(g->vs); pd->VS.BytecodeLength = g->vs->lpVtbl->GetBufferSize(g->vs);
    pd->PS.pShaderBytecode = g->ps->lpVtbl->GetBufferPointer(g->ps); pd->PS.BytecodeLength = g->ps->lpVtbl->GetBufferSize(g->ps);
    pd->InputLayout.pInputElementDescs = il; pd->InputLayout.NumElements = 2;
    pd->BlendState.RenderTarget[0].RenderTargetWriteMask = 15;
    if (variant & 1) {
        pd->BlendState.RenderTarget[0].BlendEnable = TRUE;
        pd->BlendState.RenderTarget[0].SrcBlend = D3D12_BLEND_SRC_ALPHA; pd->BlendState.RenderTarget[0].DestBlend = D3D12_BLEND_INV_SRC_ALPHA;
        pd->BlendState.RenderTarget[0].BlendOp = D3D12_BLEND_OP_ADD;
        pd->BlendState.RenderTarget[0].SrcBlendAlpha = D3D12_BLEND_ONE; pd->BlendState.RenderTarget[0].DestBlendAlpha = D3D12_BLEND_ZERO;
        pd->BlendState.RenderTarget[0].BlendOpAlpha = D3D12_BLEND_OP_ADD;
    }
    pd->RasterizerState.FillMode = D3D12_FILL_MODE_SOLID;
    pd->RasterizerState.CullMode = (variant & 2) ? D3D12_CULL_MODE_BACK : D3D12_CULL_MODE_NONE;
    pd->RasterizerState.FrontCounterClockwise = (variant & 4) != 0;
    pd->RasterizerState.SlopeScaledDepthBias = (variant & 8) ? 1.5f : 0.0f;
    pd->DSVFormat = DXGI_FORMAT_D32_FLOAT_S8X24_UINT;
    pd->DepthStencilState.DepthEnable = TRUE; pd->DepthStencilState.DepthWriteMask = D3D12_DEPTH_WRITE_MASK_ALL;
    pd->DepthStencilState.DepthFunc = D3D12_COMPARISON_FUNC_LESS_EQUAL;
    pd->SampleMask = 0xFFFFFFFFu; pd->PrimitiveTopologyType = D3D12_PRIMITIVE_TOPOLOGY_TYPE_TRIANGLE;
    pd->NumRenderTargets = 1; pd->RTVFormats[0] = (variant & 16) ? DXGI_FORMAT_R16G16B16A16_FLOAT : DXGI_FORMAT_R8G8B8A8_UNORM;
    pd->SampleDesc.Count = 1;
}

/* The renderer's call pattern (patched build_pso). Returns 1 on library hit. */
static int draw_pso(const gpu* g, int variant, int* created_ok)
{
    D3D12_GRAPHICS_PIPELINE_STATE_DESC pd; D3D12_INPUT_ELEMENT_DESC il[2];
    make_desc(g, &pd, il, variant);
    rsp_rt_query q;
    ID3D12PipelineState* pso = rsp_rt_pso_lookup(&q, g->dev, g_user, &pd, g->vs_hash, g->vs_len, g->ps_hash, g->ps_len);
    const int hit = pso != NULL;
    HRESULT hr = S_OK;
    if (!pso) {
        hr = g->dev->lpVtbl->CreateGraphicsPipelineState(g->dev, &pd, &IID_ID3D12PipelineState, (void**)&pso);
        rsp_rt_pso_created(&q, hr, 1);
    }
    if (created_ok) *created_ok = SUCCEEDED(hr) && pso;
    if (pso) pso->lpVtbl->Release(pso);
    return hit;
}

static void test_record_roundtrip(const gpu* g)
{
    for (int v = 0; v < 32; v++) {
        D3D12_GRAPHICS_PIPELINE_STATE_DESC pd, back; D3D12_INPUT_ELEMENT_DESC il[2], il2[RSP_MAX_INPUTS];
        make_desc(g, &pd, il, v);
        rsp_shader_ref vs, ps; rsp_pso_record a, b;
        rsp_shader_ref_fill(&vs, 'V', g->vs_hash, g->vs_len, pd.VS.pShaderBytecode, pd.VS.BytecodeLength);
        rsp_shader_ref_fill(&ps, 'P', g->ps_hash, g->ps_len, pd.PS.pShaderBytecode, pd.PS.BytecodeLength);
        CHECK(rsp_record_from_desc(&a, &pd, 42, &vs, &ps));
        rsp_desc_from_record(&back, il2, &a, g->root, pd.VS.pShaderBytecode, pd.VS.BytecodeLength,
                             pd.PS.pShaderBytecode, pd.PS.BytecodeLength);
        CHECK(rsp_record_from_desc(&b, &back, 42, &vs, &ps) && memcmp(&a, &b, sizeof a) == 0);
        if (v) {
            rsp_pso_record c; D3D12_GRAPHICS_PIPELINE_STATE_DESC other; make_desc(g, &other, il, 0);
            rsp_record_from_desc(&c, &other, 42, &vs, &ps);
            CHECK(rsp_key_cmp((rsp_key[]){rsp_record_key(&a)}, (rsp_key[]){rsp_record_key(&c)}) != 0);
        }
    }
    printf("record roundtrip checks done\n");
}

static void patch_library(size_t offset, uint8_t xor_value)
{
    char path[MAX_PATH]; snprintf(path, sizeof path, "%s\\%s", g_user, RSP_LIBRARY_NAME);
    size_t n; uint8_t* p = (uint8_t*)read_file(path, &n);
    if (p && offset < n) { p[offset] ^= xor_value; write_file(path, p, n); }
    free(p);
}

static void test_pso_library(gpu* g)
{
    char out[65536];
    int ok = 0;
    rsp_rt_reset();
    /* a: no library yet -> create normally, record descriptor */
    CHECK(draw_pso(g, 0, &ok) == 0 && ok && g_rsp.pso_created_unknown == 1 && g_rsp.pso_recorded == 1);
    CHECK(g_rsp.library_status == RSP_LIB_ABSENT);
    /* the same descriptor again in this session is known now, not re-recorded */
    CHECK(draw_pso(g, 0, &ok) == 0 && g_rsp.pso_recorded == 1 && g_rsp.pso_created_known == 1);
    /* b: preparation builds the library */
    int code = run_prep(NULL, out, sizeof out);
    printf("prep#1 exit=%d\n%s", code, out);
    CHECK(code == 0 && strstr(out, "\"status\":\"complete\"") && json_last_number(out, "created") == 1);
    /* c: next session loads the library and hits */
    rsp_rt_reset();
    CHECK(draw_pso(g, 0, &ok) == 1 && g_rsp.library_status == RSP_LIB_LOADED && g_rsp.pso_library_hits == 1);
    /* d: unseen variant -> safe create + record */
    CHECK(draw_pso(g, 1, &ok) == 0 && ok && g_rsp.pso_created_unknown == 1 && g_rsp.pso_recorded == 1);
    for (int v = 2; v < 8; v++) draw_pso(g, v, &ok);
    CHECK(g_rsp.pso_recorded == 7);
    /* e: cancellation after 2 new PSOs, then resume */
    code = run_prep("--cancel-after 2 --checkpoint-every 1", out, sizeof out);
    printf("prep#2 (cancel) exit=%d\n%s", code, out);
    CHECK(code == 2 && strstr(out, "\"status\":\"cancelled\"") && json_last_number(out, "created") == 2 &&
          json_last_number(out, "already") <= 1);
    code = run_prep(NULL, out, sizeof out);
    printf("prep#3 (resume) exit=%d\n%s", code, out);
    CHECK(code == 0 && strstr(out, "\"status\":\"complete\"") && json_last_number(out, "already") == 3 &&
          json_last_number(out, "created") == 5);
    rsp_rt_reset();
    int hits = 0; for (int v = 0; v < 8; v++) hits += draw_pso(g, v, &ok);
    CHECK(hits == 8 && g_rsp.pso_created_known == 0 && g_rsp.pso_created_unknown == 0);
    /* status mode: up to date */
    code = run_prep("--status", out, sizeof out);
    CHECK(code == 0 && strstr(out, "\"needed\":0"));
    /* f: different driver identity -> library refused, PSOs still created */
    patch_library(offsetof(rsp_library_header, umd_lo), 1);
    rsp_rt_reset();
    CHECK(draw_pso(g, 0, &ok) == 0 && ok && g_rsp.library_status == RSP_LIB_IDENTITY_MISMATCH && g_rsp.pso_created_known == 1);
    code = run_prep("--status", out, sizeof out);
    CHECK(code == 10 && strstr(out, "\"needed\":1"));
    /* g: prep rebuilds for the real identity */
    code = run_prep(NULL, out, sizeof out);
    printf("prep#4 (identity rebuild) exit=%d\n%s", code, out);
    CHECK(code == 0 && strstr(out, "\"library_at_start\":\"identity-mismatch\"") && json_last_number(out, "created") == 8);
    rsp_rt_reset();
    CHECK(draw_pso(g, 3, &ok) == 1 && g_rsp.library_status == RSP_LIB_LOADED);
    /* h: corrupt library blob -> refused */
    patch_library(sizeof(rsp_library_header) + 100, 0x55);
    rsp_rt_reset();
    CHECK(draw_pso(g, 3, &ok) == 0 && ok && g_rsp.library_status == RSP_LIB_CORRUPT);
    code = run_prep(NULL, out, sizeof out);
    CHECK(code == 0 && strstr(out, "\"library_at_start\":\"corrupt\""));
    /* i: truncated tail in the observed file keeps earlier records */
    char observed[MAX_PATH]; snprintf(observed, sizeof observed, "%s\\%s", g_user, RSP_OBSERVED_NAME);
    FILE* f = fopen(observed, "ab"); const uint32_t junk[3] = { RSP_CHUNK_PSOD, sizeof(rsp_pso_record), 0 };
    fwrite(junk, sizeof junk, 1, f); fwrite("xx", 2, 1, f); fclose(f);
    rsp_rt_reset();
    CHECK(draw_pso(g, 5, &ok) == 1 && g_rsp.known.count == 8 && g_rsp.known.corrupt_chunks == 1);
    /* j: library disabled by switch -> normal creation */
    _putenv_s("RSX_NO_PSO_LIBRARY", "1"); rsp_rt_reset();
    CHECK(draw_pso(g, 5, &ok) == 0 && ok && g_rsp.pso_created_known == 1);
    _putenv_s("RSX_NO_PSO_LIBRARY", "");
    /* k: missing shader -> counted, not prepared, still complete for the rest */
    char vs_file[MAX_PATH];
    snprintf(vs_file, sizeof vs_file, "%s\\V_%016llX_%08X.bin", g_user, (unsigned long long)g->vs_hash, g->vs_len);
    CHECK(DeleteFileA(vs_file));
    code = run_prep("--rebuild", out, sizeof out);
    CHECK(json_last_number(out, "missing_shader") == 8 && json_last_number(out, "created") == 0);
    printf("pso library checks done\n");
}

int main(int argc, char** argv)
{
    if (argc < 4) { fprintf(stderr, "usage: rsp_selftest <new work dir> <seed fixtures> <MacrossShaderPrep.exe> [--warp]\n"); return 2; }
    g_warp = argc > 4 && !strcmp(argv[4], "--warp");
    GetFullPathNameA(argv[1], MAX_PATH, g_work, NULL);
    GetFullPathNameA(argv[3], MAX_PATH, g_prep, NULL);
    if (!CreateDirectoryA(g_work, NULL)) { fprintf(stderr, "work dir must be new\n"); return 2; }
    snprintf(g_user, sizeof g_user, "%s\\user", g_work); snprintf(g_seed, sizeof g_seed, "%s\\seed", g_work);
    CreateDirectoryA(g_user, NULL); CreateDirectoryA(g_seed, NULL);
    _putenv_s("RSX_SHADER_CACHE_DIR", g_user);
    _putenv_s("RSX_SHADER_SEED_DIR", g_seed);
    _putenv_s("RSX_PSO_INVENTORY", "");

    test_dxbc(argv[2]);
    char vs_path[MAX_PATH], ps_path[MAX_PATH];
    snprintf(vs_path, sizeof vs_path, "%s\\V_E0B598F77DBD16F4_00002C1F.bin", argv[2]);
    snprintf(ps_path, sizeof ps_path, "%s\\P_19F3F1E7D256FEA3_00006D82.bin", argv[2]);
    fixture vs, ps;
    CHECK(load_fixture(vs_path, &vs) && load_fixture(ps_path, &ps));
    test_loader(&vs, &ps);
    test_builtin();
    gpu g;
    CHECK(make_gpu(&g));
    if (g.dev) {
        test_record_roundtrip(&g);
        test_pso_library(&g);
        rsp_adapter_identity id = rsp_query_adapter(g.dev);
        printf("adapter %ls vendor=%04X device=%04X umd=%llu library_supported=%d\n", id.description, id.vendor_id,
               id.device_id, (unsigned long long)id.umd, rsp_library_supported(g.dev));
    }
    printf("%s checks=%d failures=%d\n", g_failures ? "FAIL" : "PASS", g_checks, g_failures);
    return g_failures ? 1 : 0;
}
